const item = $input.first().json;
const body = item.body || item;

const firma = (body.firma || '').trim();
if (!firma) {
  return [{ json: { mode: 'error', message: 'Firma fehlt' } }];
}

let website = (body.website || '').trim();
if (website && !/^https?:\/\//i.test(website)) website = 'https://' + website;

return [{
  json: {
    mode: 'research',
    contact_id: body.contact_id || '',
    crm_mode: body.mode || 'free',
    firma,
    website,
    stadt: (body.stadt || '').trim(),
    gewerk: (body.gewerk || '').trim(),
    notiz: (body.notiz || '').trim(),
    website_ok: false,
    http_status: null
  }
}];

const base = $('Auth & Input').item.json;
const httpItem = $input.first().json;
const status = httpItem.statusCode || httpItem.status || 0;
const ok = status >= 200 && status < 400;
return [{ json: Object.assign({}, base, { website_ok: ok, http_status: status || null }) }];

