const err = $input.first().json;
const msg = err.errorMessage || err.message || err.error || err.description || 'Gemini-Recherche fehlgeschlagen — API-Key/Credentials in n8n prüfen';
return [{ json: { mode: 'error', message: msg } }];

const item = $input.first().json;
let base = {};
try { base = JSON.parse(item.prep_json || '{}'); } catch (e) { base = {}; }
if (!base.firma) {
  try { base = $('Merge HTTP Status').first().json; } catch (e2) {}
}
if (!base.firma) {
  try { base = $('No Website Skip').first().json; } catch (e3) {}
}
let parsed = null;
let raw = item.output || '';
if (raw && typeof raw === 'object') parsed = raw;
else if (raw) {
  try {
    parsed = JSON.parse(String(raw).replace(/```json|```/g, '').trim());
  } catch (e) { /* try below */ }
}
if (!parsed && item.summary) parsed = item;
if (!parsed) {
  return [{ json: { mode: 'error', message: raw ? ('JSON-Parse fehlgeschlagen') : 'Keine Gemini-Antwort' } }];
}
try {
  const report = {
    website: parsed.website || base.website || '',
    website_ok: base.website_ok === true,
    http_status: base.http_status,
    kontakt: parsed.kontakt || '',
    telefon: parsed.telefon || '',
    email: parsed.email || '',
    summary: parsed.summary || '',
    gaps: Array.isArray(parsed.gaps) ? parsed.gaps : [],
    hooks: Array.isArray(parsed.hooks) ? parsed.hooks : [],
    confidence: parsed.confidence || 'mittel',
    sources: Array.isArray(parsed.sources) ? parsed.sources : []
  };
  return [{ json: { mode: 'ok', ok: true, report } }];
} catch (e) {
  return [{ json: { mode: 'error', message: 'JSON-Parse: ' + e.message } }];
}
